{
  "name": "getUnifiedFolder",
  "type": "function",
  "description": "Get one of the special unified mailbox folders, which are virtual search folders and return the content from all mail accounts. Throws if the requested folder does not exist.",
  "async": "callback",
  "parameters": [
    {
      "name": "type",
      "type": "string",
      "description": "The requested unified mailbox folder type.",
      "enum": [
        "inbox",
        "drafts",
        "sent",
        "trash",
        "templates",
        "archives",
        "junk"
      ]
    },
    {
      "name": "includeSubFolders",
      "description": "Specifies whether the returned $(ref:folders.MailFolder) should populate its <var>subFolders</var> property and include all its (nested!) subfolders. Defaults to <var>false</var>.",
      "optional": true,
      "default": false,
      "type": "boolean"
    },
    {
      "type": "function",
      "name": "callback",
      "optional": true,
      "parameters": [
        {
          "$ref": "folders.MailFolder"
        }
      ]
    }
  ]
},
{
  "name": "getTagFolder",
  "type": "function",
  "description": "Get one of the special virtual tag folders, which are virtual search folders and group messages from all mail accounts based on their tags. Throws if the requested folder does not exist.",
  "async": "callback",
  "parameters": [
    {
      "name": "key",
      "type": "string",
      "description": "The tag key of the requested folder. See $(ref:messages.tags.list) for the available tags. Throws when specifying an invalid tag key."
    },
    {
      "type": "function",
      "name": "callback",
      "optional": true,
      "parameters": [
        {
          "$ref": "folders.MailFolder"
        }
      ]
    }
  ]
},
